import type {FC} from 'react';
import React from 'react';

import {useColorGenerator, useThemeType} from '@gravity-ui/uikit';

import {cnQueueIcon} from './QueueIcon.classname';

import './QueueIcon.scss';

export type QueueIconProps = {
    className?: string;
    queueId: string;
    size?: number;
    fontSize?: number;
};

export const QueueIcon: FC<QueueIconProps> = ({
    className,
    queueId,
    size = 24,
    fontSize = 0.4 * size,
}) => {
    const theme = useThemeType();
    const randomColor = useColorGenerator({seed: queueId, theme});
    const color = `rgb(${randomColor.rgb.r},${randomColor.rgb.g},${randomColor.rgb.b})`;

    return (
        <div
            className={cnQueueIcon(null, className)}
            aria-hidden
            style={{
                minWidth: size,
                width: size,
                height: size,
                borderRadius: (6 / 24) * size,
                borderWidth: (1.6 / 24) * size,
                borderColor: color,
                fontSize: fontSize,
                color,
            }}
        >
            {queueId.slice(0, 2)}
        </div>
    );
};
